{"success": true, "content": "from typing import List


def _require_int_list(name: str, values: List[int]) -> List[int]:
    if not isinstance(values, list):
        raise TypeError(f"{name} must be a list")
    for value in values:
        if not isinstance(value, int):
            raise TypeError("values must be integers")
    return values


def _in_both(value: int, right: List[int]) -> bool:
    return value in right


def sorted_intersection(left: List[int], right: List[int]) -> List[int]:
    """Return sorted unique integers present in both input lists.

    The output should contain each shared integer once, regardless of duplicate
    appearances in either input, and should be sorted ascending.
    """
    left = _require_int_list("left", left)
    right = _require_int_list("right", right)
    common = []
    for value in left:
        if _in_both(value, right):
            common.append(value)
    return sorted(common)
"}

{"success": true, "content": "def _require_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError("password must be a string")
    return password


def _has_upper(password: str) -> bool:
    return any(ch.isupper() for ch in password)


def _has_lower(password: str) -> bool:
    return any(ch.islower() for ch in password)


def _has_digit(password: str) -> bool:
    return any(ch.isdigit() for ch in password)


def _has_symbol(password: str) -> bool:
    return any(not ch.isalnum() for ch in password)


def is_strong_password(password: str) -> bool:
    """Return True when password has length >= 8, upper, lower, digit, and symbol.

    Symbols are any non-alphanumeric characters. Exactly eight characters is
    long enough when the other requirements are satisfied.
    """
    password = _require_password(password)
    long_enough = len(password) >= 8
    return (
        long_enough
        and _has_upper(password)
        and _has_lower(password)
        and _has_digit(password)
        and _has_symbol(password)
    )
"}

